"""Kickoff 52 analysis, fixed before the data (section 3 of the kickoff; k52-rule.md).

Per M (143, then 144), from the counts of the 80 circuit positions (40 circuits, 2 copies each):
- F_no(phi) and F_ref: the squared Hellinger overlap with the wait test's phi = 0 parity ideal (manacitra.wait), pooled
  over the two copies; the outcome keys in the repository's order (tests/_reuse_runs.py, _wait_test_keys).
- M's P(1) from its own bit (c5), pooled over the two copies; loss = P(1) - P(1) of Z.
- The fit: y(phi) = c + b cos(phi) + s sin(phi), ordinary least squares over the six phases. R0 and R1: y = loss,
  theta = atan2(s, -b). W-no: y = F_no, theta = atan2(-s, b). A loss a sin^2((phi + theta)/2) + const, or an F of
  f cos^2((phi + theta)/2) + const, gives theta in all three.
- Delta = theta_W - theta_R0, wrapped to (-180, +180]. Beside: theta_W - theta_R1 and theta_R1 - theta_R0; which Ramsey
  sits closer to the wait test; each fit's amplitude sqrt(b^2 + s^2) and residuals; d0(phi) and d1(phi).
- 90% intervals (5th and 95th percentiles) from one joint bootstrap, seed 52, 10,000 draws, refitting on every
  resample, in a fixed order: M by M; F for W-no at 0, 60, ..., 300, then W-ref (copies with replacement, each redrawn
  from a multinomial); then P(1) for Z, R0 at the six phases, R1 at the six phases (copies with replacement, each
  redrawn binomially). Each resample's angle difference is wrapped to within 180 degrees of the point estimate.

H52a on 143, H52b on 144: DIFFERENT if Delta's interval lies entirely outside [-5, +5] degrees; SAME if entirely inside;
NOT SETTLED otherwise.

Usage: python analyse_52.py                 (Kickoff 52's files)
       python analyse_52.py --synthetic     (stated Delta of 0 and 20 degrees at theta 0 and -100 degrees)"""
from __future__ import annotations

import hashlib
import json
import math
import sys
import time
from collections import defaultdict
from datetime import datetime, timezone
from pathlib import Path

import numpy as np

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE / "site"))
sys.path.insert(0, str(HERE / "src-a55354d" / "tests"))
from manacitra import wait as W  # noqa: E402
import _reuse_runs as reuse  # noqa: E402

ORDER_M = ("143", "144")
VERDICT_NAME = {"143": "H52a", "144": "H52b"}
PHIS = (0, 60, 120, 180, 240, 300)
SEED, N_BOOT = 52, 10_000
MARGIN_DEG = 5.0
CAL_K51_UTC = datetime(2026, 10, 13, 17, 32, 21, tzinfo=timezone.utc)
_X = np.column_stack([np.ones(6), np.cos(np.radians(PHIS)), np.sin(np.radians(PHIS))])
_PINV = np.linalg.pinv(_X)

pct = reuse.pct


def sha(p):
    return hashlib.sha256(Path(p).read_bytes()).hexdigest()


def wrap(x):
    """Degrees wrapped to (-180, +180]."""
    w = (np.asarray(x, float) + 180.0) % 360.0 - 180.0
    return np.where(w <= -180.0, w + 360.0, w)


def fit(y):
    """OLS of y(phi) = c + b cos(phi) + s sin(phi) over the six phases; y has the phases on its last axis."""
    y = np.asarray(y, float)
    coef = y @ _PINV.T
    return coef[..., 0], coef[..., 1], coef[..., 2]


def theta_R(y):
    _, b, s = fit(y)
    return np.degrees(np.arctan2(s, -b))


def theta_W(y):
    _, b, s = fit(y)
    return np.degrees(np.arctan2(-s, b))


def near(draws, point):
    """Resampled angle differences wrapped to within 180 degrees of the point estimate."""
    return point + wrap(np.asarray(draws) - point)


def verdict_of(ci):
    lo, hi = ci
    if lo > MARGIN_DEG or hi < -MARGIN_DEG:
        return "DIFFERENT"
    if lo > -MARGIN_DEG and hi < MARGIN_DEG:
        return "SAME"
    return "NOT SETTLED"


def analyse(labels, counts):
    keys, q = reuse._wait_test_keys()

    def F(V):
        return np.sqrt(V / V.sum(-1, keepdims=True) * q).sum(-1) ** 2

    cells, bits, pooled = defaultdict(list), defaultdict(list), defaultdict(lambda: defaultdict(int))
    for lab, cts in zip(labels, counts):
        key = (str(lab["M"]), lab["circuit"], lab["phi_deg"])
        if lab["part"] == "W":
            d = defaultdict(int)
            for k, n in cts.items():
                kk = k.replace(" ", "")[-W.WAIT_TEST_CLBITS:]
                d[kk] += n
                pooled[key][kk] += n
            cells[key].append((lab["copy"], [d.get(k, 0) for k in keys]))
        else:
            i = lab["m_clbit"]
            ones = sum(n for k, n in cts.items() if k.replace(" ", "")[::-1][i] == "1")
            bits[key].append((lab["copy"], ones, sum(cts.values())))
    for dd in (cells, bits):
        for k in dd:
            dd[k].sort(key=lambda x: x[0])

    rng = np.random.default_rng(SEED)

    def draw_F(key):
        V = np.array([x[1] for x in cells[key]], float)
        freq = V / V.sum(1, keepdims=True)
        idx = rng.integers(0, V.shape[0], size=(N_BOOT, V.shape[0]))
        return F(rng.multinomial(int(V[0].sum()), freq[idx]).sum(1))

    def draw_P(key):
        o = np.array([x[1] for x in bits[key]])
        t = np.array([x[2] for x in bits[key]])
        acc1, accn = np.zeros(N_BOOT), np.zeros(N_BOOT)
        for _ in range(len(o)):
            pick = rng.integers(0, len(o), size=N_BOOT)
            acc1 += rng.binomial(t[pick], o[pick] / t[pick])
            accn += t[pick]
        return acc1 / accn

    ideal = W.wait_test_ideal()
    out = {}
    for M in ORDER_M:
        wkeys = [(M, "W-no", p) for p in PHIS] + [(M, "W-ref", 0)]
        rkeys = [(M, "Z", 0)] + [(M, c, p) for c in ("R0", "R1") for p in PHIS]
        Fb = {k: draw_F(k) for k in wkeys}
        Pb = {k: draw_P(k) for k in rkeys}
        Fp = {k: W.fidelity(dict(pooled[k]), ideal) for k in wkeys}
        P = {k: sum(x[1] for x in bits[k]) / sum(x[2] for x in bits[k]) for k in rkeys}
        z = (M, "Z", 0)
        y = {"W": np.array([Fp[(M, "W-no", p)] for p in PHIS])}
        yb = {"W": np.stack([Fb[(M, "W-no", p)] for p in PHIS], -1)}
        for c in ("R0", "R1"):
            y[c] = np.array([P[(M, c, p)] - P[z] for p in PHIS])
            yb[c] = np.stack([Pb[(M, c, p)] - Pb[z] for p in PHIS], -1)
        th = {"W": float(theta_W(y["W"])), "R0": float(theta_R(y["R0"])), "R1": float(theta_R(y["R1"]))}
        thb = {"W": theta_W(yb["W"]), "R0": theta_R(yb["R0"]), "R1": theta_R(yb["R1"])}
        diffs = {}
        for name, (a, b) in (("Delta_W_minus_R0", ("W", "R0")), ("W_minus_R1", ("W", "R1")), ("R1_minus_R0", ("R1", "R0"))):
            pt = float(wrap(th[a] - th[b]))
            diffs[name] = {"deg": pt, "ci90": pct(near(wrap(thb[a] - thb[b]), pt))}
        fits = {}
        for c in ("W", "R0", "R1"):
            c0, b, s = fit(y[c])
            fits[c] = {"theta_deg": th[c], "theta_ci90": pct(near(thb[c], th[c])), "c": float(c0), "b": float(b), "s": float(s),
                       "amplitude": float(math.hypot(b, s)), "residuals": (y[c] - _X @ np.array([c0, b, s])).tolist(),
                       "y": y[c].tolist(), "label": "a fit (OLS of c + b cos phi + s sin phi over the six phases), fixed before the data"}
        f_ref, f_ref_b = Fp[(M, "W-ref", 0)], Fb[(M, "W-ref", 0)]
        resid = {}
        for t, c in (("d0", "R0"), ("d1", "R1")):
            resid[t] = {str(p): float(y["W"][i] - f_ref * (1 - y[c][i])) for i, p in enumerate(PHIS)}
            resid[t + "_ci90"] = {str(p): pct(yb["W"][:, i] - f_ref_b * (1 - yb[c][:, i])) for i, p in enumerate(PHIS)}
        out[M] = {"verdict_name": VERDICT_NAME[M], "verdict": verdict_of(diffs["Delta_W_minus_R0"]["ci90"]), **diffs, "fits": fits,
                  "R1_closer_than_R0": abs(diffs["W_minus_R1"]["deg"]) < abs(diffs["Delta_W_minus_R0"]["deg"]),
                  "F_no": {str(p): Fp[(M, "W-no", p)] for p in PHIS}, "F_no_ci90": {str(p): pct(Fb[(M, "W-no", p)]) for p in PHIS},
                  "F_ref": f_ref, "F_ref_ci90": pct(f_ref_b), "P1_Z": P[z], "P1_Z_ci90": pct(Pb[z]),
                  "loss": {f"{c}|{p}": float(y[c][i]) for c in ("R0", "R1") for i, p in enumerate(PHIS)},
                  "loss_ci90": {f"{c}|{p}": pct(yb[c][:, i]) for c in ("R0", "R1") for i, p in enumerate(PHIS)}, **resid}
    return {"H52a": out["143"]["verdict"], "H52b": out["144"]["verdict"], "per_M": out}


def exact_fit_check():
    """Section 1, check 5: the fit on the exact values (F = cos^2(phi/2), P(1) = sin^2(phi/2)) gives theta 0 and Delta 0."""
    r = np.array([math.sin(math.radians(p) / 2) ** 2 for p in PHIS])
    w = np.array([math.cos(math.radians(p) / 2) ** 2 for p in PHIS])
    tr, tw = float(theta_R(r)), float(theta_W(w))
    return {"theta_R_exact": tr, "theta_W_exact": tw, "Delta_exact": float(wrap(tw - tr)), "pass": abs(tr) < 1e-9 and abs(tw) < 1e-9}


def synthetic():
    """Counts drawn from stated distributions through the same code: the Ramsey loss a sin^2((phi + theta)/2) (a 0.9),
    the wait test's F_no f cos^2((phi + theta + Delta)/2) (f 0.9), at theta 0 and -100 degrees and Delta 0 and 20 degrees."""
    ideal = W.wait_test_ideal()
    ik = sorted(ideal)
    rng = np.random.default_rng(7)

    def w_counts(f, n=4000):
        p = {k: f / 32 for k in ik}
        p["000001"] = 1 - f
        ks = list(p)
        x = rng.multinomial(n, [p[k] for k in ks])
        return {k: int(v) for k, v in zip(ks, x) if v}

    def r_counts(p1, n=4000):
        o = int(rng.binomial(n, min(max(p1, 0.0), 1.0)))
        return {"000000": n - o, "100000": o}

    s2 = lambda x: math.sin(math.radians(x) / 2) ** 2
    c2 = lambda x: math.cos(math.radians(x) / 2) ** 2
    for theta in (0, -100):
        for delta in (0, 20):
            labels, counts = [], []
            for M in ORDER_M:
                for cp in (1, 2):
                    for p in PHIS:
                        labels.append({"M": int(M), "part": "W", "circuit": "W-no", "phi_deg": p, "copy": cp}); counts.append(w_counts(0.9 * c2(p + theta + delta)))
                        for c in ("R0", "R1"):
                            labels.append({"M": int(M), "part": "R", "circuit": c, "phi_deg": p, "copy": cp, "m_clbit": 5}); counts.append(r_counts(0.01 + 0.9 * s2(p + theta)))
                    labels.append({"M": int(M), "part": "W", "circuit": "W-ref", "phi_deg": 0, "copy": cp}); counts.append(w_counts(0.9))
                    labels.append({"M": int(M), "part": "R", "circuit": "Z", "phi_deg": 0, "copy": cp, "m_clbit": 5}); counts.append(r_counts(0.01))
            r = analyse(labels, counts)
            want = "SAME" if delta == 0 else "DIFFERENT"
            got = {M: (r["per_M"][M]["verdict"], round(r["per_M"][M]["Delta_W_minus_R0"]["deg"], 2), [round(x, 2) for x in r["per_M"][M]["Delta_W_minus_R0"]["ci90"]]) for M in ORDER_M}
            print(f"synthetic theta {theta:+d} Delta {delta}: expect {want}; got {got}; {'PASS' if all(v[0] == want for v in got.values()) else 'FAIL'}")
